import{_ as e,o,c as r,a2 as d}from"./chunks/framework.gtmkOXzY.js";const g=JSON.parse('{"title":"Ground services","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/ground-services.md","filePath":"ms-flightsim/ground-services.md","lastUpdated":null}'),a={name:"ms-flightsim/ground-services.md"};function n(i,t,s,c,l,h){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="ground-services" tabindex="-1">Ground services <a class="header-anchor" href="#ground-services" aria-label="Permalink to &quot;Ground services&quot;">​</a></h1><p>Ground crew sign on at an airport, take handling jobs on parked aircraft, drive out in the right vehicle, and get paid for each service.</p><h2 id="who-can-work-it" tabindex="-1">Who can work it <a class="header-anchor" href="#who-can-work-it" aria-label="Permalink to &quot;Who can work it&quot;">​</a></h2><p>By default anyone can sign on as ground crew. To limit it to one job, set these in <code>Config.GroundServices</code>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Turns ground services on or off</td></tr><tr><td><code>requireJob</code></td><td><code>false</code></td><td><code>true</code> = only players with <code>crewJob</code> can sign on</td></tr><tr><td><code>crewJob</code></td><td><code>&#39;groundcrew&#39;</code></td><td>The framework job used when <code>requireJob = true</code></td></tr><tr><td><code>minGrade</code></td><td><code>0</code></td><td>Lowest grade of that job allowed to sign on</td></tr></tbody></table><p>Players without the job are told &quot;You do not have the ground-crew job.&quot;</p><h2 id="signing-on" tabindex="-1">Signing on <a class="header-anchor" href="#signing-on" aria-label="Permalink to &quot;Signing on&quot;">​</a></h2><p>You work the airport you sign on at, and you only see its jobs.</p><ol><li>Go to the ground-services board and press <strong>E</strong>. This hands you the pointer for the screen.</li><li>Click the button on the screen to sign on.</li><li>Open jobs at your airport appear on the board and as blips on your map.</li></ol><p>You can also open the same crew menu with a command:</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/groundservices</code></td><td>On foot: opens the crew board. In an aircraft: opens the pilot request menu.</td></tr><tr><td><code>/gscrew</code></td><td>Opens the crew board</td></tr></tbody></table><p>You must stand inside an airport to sign on. If you leave the airport, you get a warning and are signed off after 15 seconds (<code>outsideAirportGraceSeconds</code>). Your job goes back on the board.</p><h2 id="the-board" tabindex="-1">The board <a class="header-anchor" href="#the-board" aria-label="Permalink to &quot;The board&quot;">​</a></h2><p>The board is a TV screen showing open jobs and who is on duty. You click its buttons to sign on, take a job and release it.</p><ul><li>LSIA has its board already placed in <code>config.lua</code>. It is the only board at LSIA.</li><li>Admins place boards at other airports in game with <code>/gsboard place</code>. Stand where crew will stand, facing the wall you want the screen on. It is saved on the server and survives restarts and updates.</li><li><code>/gsboard remove</code> removes the board you stand next to (within 8 m). <code>/gsboard list</code> prints all placed boards to the F8 console.</li><li>The <strong>Screens</strong> tab in <code>/adminps</code> lists every board. From there admins can go to, move or remove boards placed in game.</li><li>Up to 12 boards can be placed in game (<code>board.maxStations</code>).</li><li>Each board has a map blip. Who sees it follows <code>Config.BlipVisibility.groundServices</code>.</li></ul><h2 id="services-and-pay" tabindex="-1">Services and pay <a class="header-anchor" href="#services-and-pay" aria-label="Permalink to &quot;Services and pay&quot;">​</a></h2><p>Each job is one aircraft with one or more services. You are paid per service as you finish it. Pay varies by up to 10% either way per job (<code>payVariation = 0.10</code>), and the board shows the exact amount.</p><table tabindex="0"><thead><tr><th>Service</th><th>Default pay</th><th>MS-E vehicle</th><th>Stock fallback</th></tr></thead><tbody><tr><td>Refuelling</td><td>$320</td><td>HD-18 Fuel (<code>mse_fuel</code>)</td><td><code>tanker</code>, <code>tanker2</code></td></tr><tr><td>Baggage</td><td>$240</td><td>TG-30 Tug (<code>mse_tug</code>) with BC-25 baggage cart, or BL-40 belt loader</td><td><code>handler</code>, <code>forklift</code></td></tr><tr><td>Catering</td><td>$200</td><td>CT-70 Catering (<code>mse_cater</code>)</td><td><code>boxville</code>, <code>mule</code></td></tr><tr><td>Water &amp; lavatory</td><td>$160</td><td>PW-15 Water (<code>mse_water</code>) or LS-12 Lavatory (<code>mse_lav</code>)</td><td><code>utillitruck2</code>, <code>utillitruck</code></td></tr><tr><td>Ground power</td><td>$140</td><td>GP-90 Ground Power (<code>mse_gpu</code>)</td><td><code>airtug</code></td></tr><tr><td>Passenger stairs</td><td>$150</td><td>PS-50 Stairs (<code>mse_stairs</code>)</td><td>none</td></tr><tr><td>Cargo pallets</td><td>$260</td><td>TG-30 Tug with PD-20 pallet dolly</td><td><code>handler</code>, <code>forklift</code></td></tr><tr><td>Pushback</td><td>$300</td><td>TG-30 Tug with TB-20 towbar</td><td><code>docktug</code>, <code>airtug</code></td></tr></tbody></table><p>The server checks the vehicle you actually use, so a fuel truck cannot do bags. Pushback is not part of the default set AI aircraft ask for on arrival.</p><h2 id="how-a-job-works" tabindex="-1">How a job works <a class="header-anchor" href="#how-a-job-works" aria-label="Permalink to &quot;How a job works&quot;">​</a></h2><ol><li>An AI aircraft parks at a stand and shuts down. In the default ground-only mode it simply appears there. About 4 seconds later it calls for handling and the job appears on the board.</li><li>Take the job from the board. A GPS route leads you to the aircraft.</li><li>Press <strong>G</strong> (or choose &quot;Get the ...&quot; in the job menu) to get the vehicle for the next service. It appears at the nearest free equipment bay. If you are within 40 m of the bay, you are put straight in it.</li><li>Work each service at the aircraft: <ul><li><strong>Hose services</strong> (fuel, water, ground power): take the nozzle or cable from the truck with <strong>E</strong> or third eye, walk it to the aircraft and plug it in. When the work is done, unplug it and put it back on the truck.</li><li><strong>Door services</strong> (catering, stairs, cargo): drive to the aircraft door and stop to dock.</li><li><strong>Baggage</strong>: a belt loader places itself at the aircraft. Carry each of the 6 bags from the cart onto the running belt.</li><li><strong>Pushback</strong>: the towbar is fitted to the MS-E tug for you. Stop the towbar at the nose gear to couple, push the aircraft back to the marker, then stop to uncouple.</li></ul></li><li>Each service pays as soon as it is done. When the last one is done, the turnaround is complete and the aircraft is released.</li><li>Bring the vehicle back to the equipment bays and press <strong>G</strong> there to hand it back.</li></ol><p>If you release a job, it goes back on the board and finished services stay finished for the next crew member.</p><h3 id="time-limits" tabindex="-1">Time limits <a class="header-anchor" href="#time-limits" aria-label="Permalink to &quot;Time limits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What happens</th></tr></thead><tbody><tr><td><code>requestTTLSeconds</code></td><td>900</td><td>A job nobody takes expires</td></tr><tr><td><code>claimTTLSeconds</code></td><td>600</td><td>A taken job nobody finishes goes back on the board</td></tr><tr><td><code>aiTurnaround.standWaitSeconds</code></td><td>240</td><td>An AI aircraft on a stand waits this long for someone to take its job</td></tr><tr><td><code>aiTurnaround.serviceMaxSeconds</code></td><td>600</td><td>Once a job is taken, the aircraft waits this long for crew to finish</td></tr><tr><td><code>aiTurnaround.departAfterServiceSeconds</code></td><td>20</td><td>The aircraft stays this long after the crew finishes</td></tr></tbody></table><h2 id="losing-a-job" tabindex="-1">Losing a job <a class="header-anchor" href="#losing-a-job" aria-label="Permalink to &quot;Losing a job&quot;">​</a></h2><p>You lose the job, unpaid for the service you were on, when:</p><ul><li>your job vehicle is wrecked or sunk,</li><li>your job vehicle disappears (deleted, cleaned up or removed by another script), or</li><li>you disconnect, including a game crash.</li></ul><p>The job goes back on the board. Unfinished services start over. Services already finished stay finished and stay paid. A pilot who asked for the service is told the crew could not finish.</p><h2 id="pilots-requesting-service" tabindex="-1">Pilots requesting service <a class="header-anchor" href="#pilots-requesting-service" aria-label="Permalink to &quot;Pilots requesting service&quot;">​</a></h2><p>Player pilots can ask for handling on their own aircraft.</p><ol><li>Park at an airport and stay in the aircraft.</li><li>Type <code>/groundservices</code>.</li><li>Tick the services you need and choose <strong>Call ground crew</strong>.</li></ol><p>Crew on duty see the request on their board at once. You get a message as each service finishes, and another when you are clear to push and start. Use <strong>Cancel my request</strong> in the same menu to cancel. You can have one open request at a time. The request costs the pilot nothing.</p><h2 id="ai-aircraft-and-crew" tabindex="-1">AI aircraft and crew <a class="header-anchor" href="#ai-aircraft-and-crew" aria-label="Permalink to &quot;AI aircraft and crew&quot;">​</a></h2><p>AI aircraft only ask for handling while crew are signed on at their airport.</p><ul><li>With no crew on duty, no new parked aircraft appear (in the default ground-only mode). An aircraft already parked leaves 20 seconds after it shuts down.</li><li>Each crew member signed on adds up to 4 open AI jobs at that airport (<code>aiDemand.jobsPerCrew</code>) and 2 different services (<code>aiDemand.servicesPerCrew</code>).</li><li>The server never holds more than 40 open jobs in total (<code>maxOpenRequests</code>).</li><li>AI aircraft do not take stands within 35 m of the spots where player job aircraft spawn (<code>Config.AITraffic.jobSpawnClearance</code>).</li></ul><h2 id="the-ms-e-ground-fleet" tabindex="-1">The MS-E ground fleet <a class="header-anchor" href="#the-ms-e-ground-fleet" aria-label="Permalink to &quot;The MS-E ground fleet&quot;">​</a></h2><p>The MS-E vehicles ship in their own resource, <code>MS_FlightSim_MSE</code>. It must be started before MS_FlightSim. Without it, crew can still use the stock fallback vehicles listed under <a href="#services-and-pay">Services and pay</a>. Passenger stairs has no stock fallback.</p><table tabindex="0"><thead><tr><th>Vehicle</th><th>Model</th><th>Used for</th></tr></thead><tbody><tr><td>MS-E TG-30 Tug</td><td><code>mse_tug</code></td><td>Baggage, cargo pallets and pushback</td></tr><tr><td>MS-E BL-40 Belt Loader</td><td><code>mse_belt</code></td><td>Baggage loading</td></tr><tr><td>MS-E GP-90 Ground Power</td><td><code>mse_gpu</code></td><td>Ground power</td></tr><tr><td>MS-E HD-18 Fuel</td><td><code>mse_fuel</code></td><td>Refuelling</td></tr><tr><td>MS-E PW-15 Water</td><td><code>mse_water</code></td><td>Water service</td></tr><tr><td>MS-E LS-12 Lavatory</td><td><code>mse_lav</code></td><td>Lavatory service</td></tr><tr><td>MS-E CT-70 Catering</td><td><code>mse_cater</code></td><td>Catering</td></tr><tr><td>MS-E PS-50 Stairs</td><td><code>mse_stairs</code></td><td>Passenger stairs</td></tr><tr><td>MS-E BC-25 Baggage Cart</td><td><code>mse_bagcart</code></td><td>Trailer, towed by the tug</td></tr><tr><td>MS-E PD-20 Pallet Dolly</td><td><code>mse_pallet</code></td><td>Trailer, towed by the tug</td></tr><tr><td>MS-E TB-20 Front Towbar</td><td><code>mse_towbar</code></td><td>Fits the tug for pushback</td></tr></tbody></table><h3 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h3><p>When you sit in the driver seat, a card on the left of the screen shows that vehicle&#39;s special keys for a few seconds.</p><table tabindex="0"><thead><tr><th>Key</th><th>Vehicle</th><th>Action</th></tr></thead><tbody><tr><td><strong>E</strong> (tap)</td><td>All powered units</td><td>Amber warning lights on or off</td></tr><tr><td><strong>E</strong> (hold)</td><td>All powered units</td><td>Horn</td></tr><tr><td><strong>H</strong> (tap)</td><td>All powered units</td><td>Headlights</td></tr><tr><td><strong>Page Up / Page Down</strong></td><td>Catering</td><td>Raise or lower the box</td></tr><tr><td><strong>H</strong> (hold)</td><td>Catering</td><td>Open or shut the rear door</td></tr><tr><td><strong>Page Up / Page Down</strong></td><td>Stairs</td><td>Raise or lower the stairs</td></tr><tr><td><strong>H</strong> (hold)</td><td>Stairs</td><td>Bridge plate out or in</td></tr><tr><td><strong>Page Up / Page Down</strong></td><td>Belt loader</td><td>Raise or lower the belt</td></tr><tr><td><strong>L</strong> (tap)</td><td>Belt loader</td><td>Belt on or off</td></tr><tr><td><strong>L</strong> (hold)</td><td>Belt loader</td><td>Run the belt backwards</td></tr><tr><td><strong>U</strong></td><td>Tug</td><td>Fit or park the towbar</td></tr><tr><td><strong>Y</strong></td><td>Tug</td><td>Couple or release the aircraft</td></tr><tr><td><strong>T</strong></td><td>Tug</td><td>Hitch or release a baggage cart</td></tr></tbody></table><p><strong>L</strong>, <strong>U</strong>, <strong>Y</strong> and <strong>T</strong> can be rebound in <strong>Settings → Key Bindings → FiveM</strong>.</p><h3 id="renting-equipment" tabindex="-1">Renting equipment <a class="header-anchor" href="#renting-equipment" aria-label="Permalink to &quot;Renting equipment&quot;">​</a></h3><p><code>/msefleet</code> opens the airport-equipment menu. Players can rent any powered MS-E vehicle for free for 15 minutes (<code>rentals.minutes</code>). Return it to an equipment bay before the time runs out, or it despawns. You cannot rent while you hold a ground-services job.</p><p>Job vehicles and rentals nobody is using are removed after 5 minutes when no player is within 60 m (<code>cleanup</code>).</p><h2 id="ai-traffic-settings" tabindex="-1">AI traffic settings <a class="header-anchor" href="#ai-traffic-settings" aria-label="Permalink to &quot;AI traffic settings&quot;">​</a></h2><p>These live in <code>Config.AITraffic</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Master switch for AI aircraft</td></tr><tr><td><code>groundOnly</code></td><td><code>true</code></td><td><code>true</code> = aircraft only appear parked on a stand, wait for crew, and leave once handled. <code>false</code> = full flying AI traffic (<strong>beta</strong>).</td></tr><tr><td><code>maxConcurrent</code></td><td><code>6</code></td><td>AI flights at once, server-wide</td></tr><tr><td><code>spawnIntervalMs</code></td><td><code>45000</code></td><td>Minimum time between new flights</td></tr><tr><td><code>maxConcurrentCap</code></td><td><code>8</code></td><td>Hard ceiling when traffic grows with player count. Raise it only if your server has entity headroom.</td></tr><tr><td><code>scaleWithPlayers</code></td><td><code>true</code></td><td>Adds one flight per 25 online players (<code>playersPerFlight</code>), up to <code>maxConcurrentCap</code></td></tr><tr><td><code>noAirports</code></td><td><code>{ &#39;Grapeseed&#39; }</code></td><td>Airports AI never departs from, flies to or lands at. Players still use them normally.</td></tr></tbody></table><p>Ground-only mode is what keeps the ground-services job supplied with work. Leave it on unless you want to test flying AI.</p><h3 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h3><p>Admins change the amount of traffic live with <code>/aitraffic preset &lt;name&gt;</code>. It needs the <code>msflightsim.admin</code> ace, or run it in the server console.</p><table tabindex="0"><thead><tr><th>Preset</th><th>Flights at once</th><th>Spawn interval</th></tr></thead><tbody><tr><td><code>light</code></td><td>3</td><td>60 s</td></tr><tr><td><code>medium</code></td><td>6</td><td>45 s</td></tr><tr><td><code>heavy</code></td><td>12</td><td>25 s</td></tr></tbody></table><p>With <code>scaleWithPlayers</code> on, <code>maxConcurrentCap</code> still limits the total, so <code>heavy</code> stops at 8 unless you raise the cap. A preset lasts until the next restart. Set <code>maxConcurrent</code> and <code>spawnIntervalMs</code> in your config to make it permanent.</p>',53)])])}const p=e(a,[["render",n]]);export{g as __pageData,p as default};
